		"The Wardens charge more quickly during phase 1."),
	ACCELERATION(39, "Acceleration", 10, Boss.WARDENS,
		"During phase 2, the Wardens attack faster and the obelisk charges faster."),
	PENETRATION(40, "Penetration", 10, Boss.WARDENS,
		"The obelisk's phase 2 attacks become more powerful."),
	OVERCLOCKED(41, "Overclocked", 10, Boss.WARDENS,
		"Speeds up Warden attacks in the final phase. Stacks with Overclocked 2."),
	OVERCLOCKED_2(42, "Overclocked 2", 10, Boss.WARDENS,
		"Further speeds up Warden attacks in the final phase. Stacks with Overclocked."),
	INSANITY(43, "Insanity", 50, Boss.WARDENS,
		"In the final phase, floor slams and phantom attacks are faster, and floor tiles disappear faster.");

	public final int uiIndex;
	public final String displayName;
	public final int raidPoints;
	public final Boss boss;
	public final String description;
	private final String matchName;

	Invocation(int uiIndex, String displayName, int raidPoints, Boss boss, String description)
	{
		this.uiIndex = uiIndex;
		this.displayName = displayName;
		this.raidPoints = raidPoints;
		this.boss = boss;
		this.description = description;
		this.matchName = normalize(displayName);
	}

	public boolean isPathInvocation()
	{
		return uiIndex >= 11 && uiIndex <= 14;
	}

	public static Invocation fromName(String name)
	{
		String normalized = normalize(name);
		for (Invocation invocation : values())
		{
			if (invocation.matchName.equals(normalized))
			{
				return invocation;
			}
		}
		return null;
	}

	private static String normalize(String text)
	{
		return text == null ? "" : text.replaceAll("<[^>]*>", "")
			.replace('\u00a0', ' ').trim().toLowerCase(Locale.ROOT);
	}
}

package com.cornwall92.toapathwatch;

import java.util.EnumMap;
import java.util.Map;

public final class InvocationReader
{
	static final int PARTY_BUILD_SCRIPT = 6729;

	private InvocationReader() {}

	/**
	 * Script 6729's input is the complete selection used to build the party screen.
	 * Read before the script runs: post-script widgets can be recoloured by other plugins.
	 * Arguments include the script ID, role, party metadata, count, score, tab and three
	 * 31-bit selection words. Roles 1/2 are a member/leader of the current party.
	 */
	public static InvocationSelection readPartyBuild(Object[] args)
	{
		if (args == null || args.length != 9) return null;
		for (Object arg : args) if (!(arg instanceof Integer)) return null;
		if ((Integer) args[0] != PARTY_BUILD_SCRIPT) return null;
		int role = (Integer) args[1];
		if (role != 1 && role != 2) return null;
		int tab = (Integer) args[5];
		if (tab < 0 || tab > 3) return null;
		int[] words = {(Integer) args[6], (Integer) args[7], (Integer) args[8]};
		int[] knownBits = new int[3];
		Map<Invocation, Boolean> states = new EnumMap<>(Invocation.class);
		int count = 0;
		for (Invocation invocation : Invocation.values())
		{
			// Cache param 1159: ordinary invocation bits are 1..44 in UI order.
			// Script 6755 splits at 31 and 62, not at 32 and 64.
			int bit = invocation.uiIndex + 1;
			int word = bit / 31;
			int mask = 1 << (bit % 31);
			knownBits[word] |= mask;
			boolean active = (words[word] & mask) != 0;
			states.put(invocation, active);
			if (active) count++;
		}
		for (int i = 0; i < words.length; i++)
		{
			// Do not silently drop event/league-only or future invocations.
			if ((words[i] & ~knownBits[i]) != 0) return null;
		}
		if (count != (Integer) args[3]) return null;
		return InvocationSelection.validate(states, (Integer) args[4]);
	}
}

package com.cornwall92.toapathwatch;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/** A complete observed selection. null at the reader boundary means unknown, not empty. */
public final class InvocationSelection
{
	public final Set<Invocation> active;
	public final int raidPoints;

	private InvocationSelection(Set<Invocation> active, int raidPoints)
	{
		this.active = Collections.unmodifiableSet(active);
		this.raidPoints = raidPoints;
	}

	public static InvocationSelection validate(Map<Invocation, Boolean> states, Integer displayedPoints)
	{
		if (states.size() != Invocation.values().length || states.containsValue(null))
		{
			return null;
		}
		EnumSet<Invocation> active = EnumSet.noneOf(Invocation.class);
		int sum = 0;
		for (Invocation inv : Invocation.values())
		{
			if (Boolean.TRUE.equals(states.get(inv)))
			{
				active.add(inv);
				sum += inv.raidPoints;
			}
		}
		if (displayedPoints != null && displayedPoints != sum)
		{
			return null;
		}
		return new InvocationSelection(active, sum);
	}
}

package com.cornwall92.toapathwatch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Static reference text, not an attack tracker. Sources and limits: RESEARCH.md. */
public final class PathMechanics
{
	private PathMechanics() {}

	public static int tier(int level)
	{
		checkLevel(level);
		return Math.min(level / 2, 2);
	}

	public static int statBonusPercent(int level)
	{
		checkLevel(level);
		return level == 0 ? 0 : 3 + 5 * level;
	}

	private static void checkLevel(int level)
	{
		if (level < 0 || level > 6)
		{
			throw new IllegalArgumentException("Path level must be 0-6");
		}
	}

	public static List<String> describe(Boss boss, int level)
	{
		if (boss == Boss.WARDENS)
		{
			return Collections.singletonList("No separate Warden path level.");
		}
		int tier = tier(level);
		List<String> lines = new ArrayList<>();
		if (tier == 0)
		{
			lines.add("No level-2/4 mechanic upgrades.");
			return Collections.unmodifiableList(lines);
		}
		switch (boss)
		{
			case AKKHA:
				lines.add("Memory Blast: " + (4 + tier) + " steps (base 4).");
				lines.add("Final-phase orbs hit harder; cap 25.");
				break;
			case BABA:
				lines.add(tier == 1 ? "Rockfall drops faster." : "Rockfall drops even faster.");
				lines.add(tier == 1 ? "Sarcophagus blasts cover more tiles." : "Sarcophagus blast area grows again.");
				lines.add("Rolling boulder base HP: " + (tier == 1 ? "27" : "31") + " (before raid scaling).");
				break;
			case KEPHRI:
				lines.add(tier == 1 ? "Faster fireball attacks." : "Fireball attacks speed up again.");
				lines.add(tier == 1 ? "Healing swarms can spawn in threes." : "Triple healing swarms occur more often.");
				break;
			case ZEBAK:
				lines.add(tier == 1 ? "Faster attacks, including enrage." : "Attacks: 5 ticks; enrage: 2 ticks.");
				lines.add("Wave gap: " + (3 - tier) + " tile" + (tier == 1 ? "s." : "."));
				break;
			default:
				throw new IllegalArgumentException("No boss supplied");
		}
		return Collections.unmodifiableList(lines);
	}
}

package com.cornwall92.toapathwatch;

/**
 * Client-thread state for a lobby capture and its frozen raid selection.
 * Unknown geography is a temporary absence of evidence, not a confirmed exit.
 */
public final class RaidSelectionTracker
{
	private static final int LOBBY_REGION = 13454;
	private static final int NEXUS_REGION = 14160;
	private static final int UNKNOWN_GRACE_TICKS = 3;
	private static final int ENTRY_SCORE_ATTEMPTS = 5;

	private boolean inRaid;
	private InvocationSelection lobbyCandidate;
	private InvocationSelection entryCandidate;
	private InvocationSelection selection;
	private int unknownTicks;
	private int scoreAttemptsRemaining;

	/** Call only with a selection read from the current party's lobby interface. */
	public void capture(InvocationSelection captured)
	{
		if (!inRaid)
		{
			lobbyCandidate = captured;
		}
	}

	public void invalidateLobby()
	{
		lobbyCandidate = null;
	}

	/**
	 * Called once per game tick in raid regions. A confirmed lobby can additionally
	 * be synchronized before accepting a party-screen capture after raid exit.
	 * A region of -1 means the local position is unknown.
	 * There are five score observations, including the first entry tick. Subsequent
	 * observations are permitted only in the nexus; entering a path closes the window.
	 */
	public void update(int region, int raidPoints)
	{
		if (region == -1)
		{
			if (++unknownTicks > UNKNOWN_GRACE_TICKS)
			{
				reset();
			}
			return;
		}
		unknownTicks = 0;

		if (!Boss.isRaidRegion(region))
		{
			if (inRaid || region != LOBBY_REGION)
			{
				reset();
			}
			return;
		}

		boolean entering = !inRaid;
		if (entering)
		{
			inRaid = true;
			entryCandidate = lobbyCandidate;
			lobbyCandidate = null;
			selection = null;
			scoreAttemptsRemaining = ENTRY_SCORE_ATTEMPTS;
		}

		if (entryCandidate == null)
		{
			return;
		}
		if (!entering && region != NEXUS_REGION)
		{
			clearEntryCandidate();
			return;
		}

		if (entryCandidate.raidPoints == raidPoints)
		{
			selection = entryCandidate;
			clearEntryCandidate();
		}
		else if (--scoreAttemptsRemaining == 0)
		{
			clearEntryCandidate();
		}
	}

	private void clearEntryCandidate()
	{
		entryCandidate = null;
		scoreAttemptsRemaining = 0;
	}

	public InvocationSelection getSelection()
	{
		return selection;
	}

	public boolean isInRaid()
	{
		return inRaid;
	}

	public void reset()
	{
		inRaid = false;
		lobbyCandidate = null;
		entryCandidate = null;
		selection = null;
		unknownTicks = 0;
		scoreAttemptsRemaining = 0;
	}
}

package com.cornwall92.toapathwatch;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import static net.runelite.api.Constants.CHUNK_SIZE;
import static net.runelite.api.Constants.SCENE_SIZE;

/** Resolves a template region without treating an unloaded instance chunk as an exit. */
public final class RegionResolver
{
	private RegionResolver() {}

	/** Must be called on the client thread. -1 means the location is not yet known. */
	public static int region(Client client)
	{
		Player player = client.getLocalPlayer();
		if (player == null) return -1;
		LocalPoint local = player.getLocalLocation();
		if (local == null) return -1;
		WorldView worldView = client.getWorldView(local.getWorldView());
		if (worldView == null) return -1;

		if (!worldView.isInstance())
		{
			return WorldPoint.fromLocal(worldView, local.getX(), local.getY(), worldView.getPlane()).getRegionID();
		}

		int sceneX = local.getSceneX();
		int sceneY = local.getSceneY();
		if (sceneX < 0 || sceneY < 0 || sceneX >= SCENE_SIZE || sceneY >= SCENE_SIZE) return -1;
		int plane = worldView.getPlane();
		int chunkX = sceneX / CHUNK_SIZE;
		int chunkY = sceneY / CHUNK_SIZE;
		int[][][] chunks = worldView.getInstanceTemplateChunks();
		if (chunks == null || plane < 0 || plane >= chunks.length || chunks[plane] == null
			|| chunkX >= chunks[plane].length || chunks[plane][chunkX] == null
			|| chunkY >= chunks[plane][chunkX].length || chunks[plane][chunkX][chunkY] == -1)
		{
			return -1;
		}
		// RuneLite's conversion assumes the chunk is loaded: -1 otherwise decodes to
		// a synthetic region rather than an unknown result, prematurely clearing a raid.
		return WorldPoint.fromLocalInstance(client, local).getRegionID();
	}
}

package com.cornwall92.toapathwatch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(ToaPathwatchConfig.GROUP)
public interface ToaPathwatchConfig extends Config
{
	String GROUP = "toa-path-info";

	@ConfigItem(keyName = "showInvocations", name = "Show invocations", description = "Show the active invocation list above the path effects", position = 0)
	default boolean showInvocations() { return true; }

	@ConfigItem(keyName = "invocationTooltips", name = "Invocation hover descriptions", description = "Show an invocation's effects when hovering over its name in the panel", position = 1)
	default boolean invocationTooltips() { return true; }

	@ConfigItem(keyName = "showGlobals", name = "Other raid invocations", description = "Include active general invocations as well as path and boss selections", position = 2)
	default boolean showGlobals() { return false; }

	@ConfigItem(keyName = "showPuzzles", name = "Show in puzzle rooms", description = "Show the path reference in its puzzle room too", position = 3)
	default boolean showPuzzles() { return false; }

	@ConfigItem(keyName = "showScaling", name = "Show path stat increase", description = "Show additional HP/damage scaling from path level only", position = 4)
	default boolean showScaling() { return true; }

	@ConfigItem(keyName = "showPoints", name = "Invocation raid points", description = "Display each invocation's contribution to the raid level", position = 5)
	default boolean showPoints() { return false; }

	@Range(min = 180, max = 450)
	@ConfigItem(keyName = "width", name = "Panel width", description = "Width of the movable reference panel", position = 6)
	default int width() { return 260; }

	@Range(min = -1, max = 100)
	@ConfigItem(keyName = "mainOpacity", name = "Main panel opacity (%)", description = "Background opacity: -1 keeps your existing RuneLite setting, 0 is transparent, 100 is solid", position = 7)
	default int mainOpacity() { return -1; }

	@Range(min = 0, max = 100)
	@ConfigItem(keyName = "popupOpacity", name = "Hover popup opacity (%)", description = "Background opacity for invocation descriptions: 0 is transparent, 100 is solid", position = 8)
	default int popupOpacity() { return 100; }
}

package com.cornwall92.toapathwatch;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.overlay.components.TooltipComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

public class ToaPathwatchOverlay extends OverlayPanel
{
	private static final Color GOLD = new Color(255, 195, 85);
	private static final Color GREEN = new Color(130, 220, 155);
	private static final int TOOLTIP_WIDTH = 300;
	private final ToaPathwatchPlugin plugin;
	private final ToaPathwatchConfig config;
	private final Client client;
	private final TooltipManager tooltipManager;
	private final RuneLiteConfig runeLiteConfig;
	private final Map<Invocation, LineComponent> invocationRows = new EnumMap<>(Invocation.class);

	@Inject
	ToaPathwatchOverlay(ToaPathwatchPlugin plugin, ToaPathwatchConfig config, Client client,
		TooltipManager tooltipManager, RuneLiteConfig runeLiteConfig)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.client = client;
		this.tooltipManager = tooltipManager;
		this.runeLiteConfig = runeLiteConfig;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setResizable(false);
	}

	private LineComponent line(String text, Color color)
	{
		LineComponent row = LineComponent.builder().left(text).leftColor(color).build();
		panelComponent.getChildren().add(row);
		return row;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		invocationRows.clear();
		// Resolve each frame so both local settings and RuneLite's background colour update live.
		setPreferredColor(withOpacity(runeLiteConfig.overlayBackgroundColor(), config.mainOpacity()));
		Boss boss = plugin.getBoss();
		if (boss == null)
		{
			String status = plugin.getLobbyStatus();
			if (status == null) return null;
			panelComponent.setPreferredSize(new Dimension(config.width(), 0));
			panelComponent.getChildren().add(TitleComponent.builder().text("ToA Pathwatch 0.1.6").color(GOLD).build());
			line(status, Color.LIGHT_GRAY);
			return super.render(graphics);
		}
		int level = plugin.getPathLevel();
		panelComponent.setPreferredSize(new Dimension(config.width(), 0));
		String title = boss.displayName + (boss == Boss.WARDENS ? "" : " - Path " + (level < 0 ? "?" : level));
		panelComponent.getChildren().add(TitleComponent.builder().text(title).color(GOLD).build());
		if (config.showInvocations()) renderInvocations(boss);
		line("Path effects", GOLD);
		if (boss == Boss.WARDENS)
		{
			line("No separate Warden path level.", Color.LIGHT_GRAY);
		}
		else if (level < 0)
		{
			line("Waiting for path level.", Color.LIGHT_GRAY);
		}
		else
		{
			if (config.showScaling()) line("Path HP / damage: +" + PathMechanics.statBonusPercent(level) + "%", Color.WHITE);
			for (String effect : PathMechanics.describe(boss, level)) line(effect, Color.WHITE);
		}
		Dimension dimension = super.render(graphics);
		// Components have their final bounds only after layout, including wrapped names.
		if (config.invocationTooltips() && !invocationRows.isEmpty() && !client.isMenuOpen())
		{
			renderTooltip(graphics.getFontMetrics(runeLiteConfig.tooltipFont().getFont()));
		}
		return dimension;
	}

	private void renderInvocations(Boss boss)
	{
		InvocationSelection selection = plugin.getSelection();
		line("Active invocations", GOLD);
		if (selection == null)
		{
			line("Not captured. Open your party's invocation tab before entering the raid.", Color.LIGHT_GRAY);
		}
		else
		{
			boolean any = false;
			for (Invocation invocation : Invocation.values())
			{
				if (selection.active.contains(invocation) && (invocation.boss == boss || invocation.isPathInvocation()
					|| (config.showGlobals() && invocation.boss == null)))
				{
					invocationRows.put(invocation, line(invocation.displayName
						+ (config.showPoints() ? " (+" + invocation.raidPoints + ")" : ""), GREEN));
					any = true;
				}
			}
			if (!any) line("None relevant enabled.", Color.LIGHT_GRAY);
		}
	}

	private void renderTooltip(FontMetrics metrics)
	{
		Point mouse = client.getMouseCanvasPosition();
		// RuneLite positions the overlay in canvas coordinates before calling render.
		int x = mouse.getX() - getBounds().x;
		int y = mouse.getY() - getBounds().y;
		for (Map.Entry<Invocation, LineComponent> entry : invocationRows.entrySet())
		{
			if (entry.getValue().getBounds().contains(x, y))
			{
				Invocation invocation = entry.getKey();
				StringBuilder text = new StringBuilder("<col=ffc355>").append(invocation.displayName).append("</col><br>");
				int width = 0;
				int space = metrics.stringWidth(" ");
				for (String word : invocation.description.split(" "))
				{
					int wordWidth = metrics.stringWidth(word);
					if (width > 0)
					{
						if (width + space + wordWidth > TOOLTIP_WIDTH)
						{
							text.append("<br>");
							width = 0;
						}
						else
						{
							text.append(' ');
							width += space;
						}
					}
					text.append(word);
					width += wordWidth;
				}
				Tooltip tooltip = new Tooltip(text.toString());
				TooltipComponent component = new TooltipComponent();
				component.setText(tooltip.getText());
				component.setBackgroundColor(withOpacity(runeLiteConfig.overlayBackgroundColor(), config.popupOpacity()));
				// A supplied TooltipComponent retains its colour; string/PanelComponent tooltips
				// are recoloured by RuneLite's TooltipOverlay using the global transparency.
				tooltip.setComponent(component);
				tooltipManager.add(tooltip);
				return;
			}
		}
	}

	private static Color withOpacity(Color color, int opacity)
	{
		if (opacity < 0) return color;
		int alpha = Math.round(Math.min(opacity, 100) * 255 / 100f);
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}
}

package com.cornwall92.toapathwatch;

import com.google.inject.Provides;
import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(name = "ToA Pathwatch", description = "Current invocations and path-level reference", tags = {"toa", "invocations", "path", "reference"})
public class ToaPathwatchPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private OverlayManager overlayManager;
	@Inject private ToaPathwatchOverlay overlay;
	@Inject private ToaPathwatchConfig config;

	private volatile boolean enabled;
	private final AtomicInteger generation = new AtomicInteger();
	private int initializedGeneration = -1;
	private boolean partyBuildPending;
	private InvocationSelection pendingSelection;
	private Integer capturedController;
	private String captureStatus = "Open your party's Invocations tab.";
	private boolean showLobbyStatus;
	private final RaidSelectionTracker selections = new RaidSelectionTracker();
	private Boss boss;
	private int pathLevel = -1;

	@Override
	protected void startUp()
	{
		enabled = true;
		int startupGeneration = generation.incrementAndGet();
		overlayManager.add(overlay);
		clientThread.invokeLater(() ->
		{
			if (enabled && generation.get() == startupGeneration)
			{
				initializeState();
				refresh();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		enabled = false;
		int shutdownGeneration = generation.incrementAndGet();
		overlayManager.remove(overlay);
		clientThread.invokeLater(() ->
		{
			if (!enabled && generation.get() == shutdownGeneration) clearState();
		});
	}

	/** Called only on the client thread, including lifecycle cleanup. */
	private void clearState()
	{
		initializedGeneration = generation.get();
		partyBuildPending = false;
		pendingSelection = null;
		capturedController = null;
		captureStatus = "Open your party's Invocations tab.";
		showLobbyStatus = false;
		selections.reset();
		boss = null;
		pathLevel = -1;
	}

	private void initializeState()
	{
		// A game event can arrive before the queued startup callback. Initialize once
		// on the client thread so that callback cannot erase a capture made meanwhile.
		if (initializedGeneration != generation.get()) clearState();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			generation.incrementAndGet();
			clearState();
		}
		else if (event.getGameState() != GameState.LOGGED_IN)
		{
			boss = null;
			pathLevel = -1;
			showLobbyStatus = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) { refresh(); }

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (!enabled) return;
		initializeState();
		if (event.getScriptId() == InvocationReader.PARTY_BUILD_SCRIPT)
		{
			partyBuildPending = event.getScriptEvent() != null;
			pendingSelection = partyBuildPending
				? InvocationReader.readPartyBuild(event.getScriptEvent().getArguments()) : null;
		}
		else if (isSelectionEdit(event) && region() == 13454)
		{
			// A click requests a change; wait for the server's next complete party build.
			// Do not let a partly changed widget grid restore the old selection meanwhile.
			invalidateCapture("Waiting for the party's updated selection.");
		}
	}

	private boolean isSelectionEdit(ScriptPreFired event)
	{
		if (event.getScriptId() == 6754) return true;
		// Script 1558 installs this shared button callback for Load and Clear All.
		// The generic handler also serves unrelated buttons, so check the component.
		if (event.getScriptId() != 1561 || event.getScriptEvent() == null) return false;
		Object[] args = event.getScriptEvent().getArguments();
		return args != null && args.length > 2
			&& (Integer.valueOf(InterfaceID.ToaPartydetails.BTN_PRESETS_LOAD).equals(args[2])
				|| Integer.valueOf(InterfaceID.ToaPartydetails.INVOCATIONS_CLEAR).equals(args[2]));
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (!enabled) return;
		initializeState();
		int id = event.getScriptId();
		if (id == InvocationReader.PARTY_BUILD_SCRIPT && partyBuildPending)
		{
			partyBuildPending = false;
			if (client.getGameState() == GameState.LOGGED_IN && region() == 13454 && partyScreenVisible())
			{
				// The party screen can reopen after raid exit before the next GameTick.
				// Settle that confirmed exit before capture() checks its in-raid guard.
				selections.update(13454, 0);
				if (pendingSelection != null) acceptCapture(pendingSelection);
				else invalidateCapture("Not captured. Reopen your own party's Invocations tab.");
			}
			pendingSelection = null;
		}
	}

	private int region()
	{
		return RegionResolver.region(client);
	}

	private boolean partyScreenVisible()
	{
		var header = client.getWidget(InterfaceID.ToaPartydetails.RAID_LEVEL);
		var grid = client.getWidget(InterfaceID.ToaPartydetails.INVOCATIONS_CONTENT);
		return (header != null && !header.isHidden()) || (grid != null && !grid.isHidden());
	}

	private void acceptCapture(InvocationSelection selection)
	{
		selections.capture(selection);
		capturedController = client.getVarpValue(VarPlayerID.TOA_MYCONTROLLER);
		setCaptureStatus("Captured " + selection.active.size() + " invocations. Raid level: " + selection.raidPoints + ".");
	}

	private void invalidateCapture(String message)
	{
		selections.invalidateLobby();
		capturedController = null;
		setCaptureStatus(message);
	}

	private void setCaptureStatus(String message)
	{
		if (!message.equals(captureStatus)) log.debug("ToA invocation capture: {}", message);
		captureStatus = message;
	}

	private void refresh()
	{
		if (!enabled || client.getGameState() != GameState.LOGGED_IN) return;
		initializeState();
		int region = region();
		// Check party changes against settled geography. A controller update can arrive
		// before the first raid GameTick; clearing from VarbitChanged loses that capture.
		if (region == 13454 && !selections.isInRaid() && capturedController != null
			&& capturedController != client.getVarpValue(VarPlayerID.TOA_MYCONTROLLER))
		{
			invalidateCapture("Party changed. Reopen your party's Invocations tab.");
		}
		boolean wasInRaid = selections.isInRaid();
		// Raid points validate an observed selection; they cannot identify invocations alone.
		selections.update(region, client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL));
		if (wasInRaid && !selections.isInRaid())
		{
			capturedController = null;
			setCaptureStatus("Open your party's Invocations tab for this raid.");
		}
		showLobbyStatus = region == 13454 && partyScreenVisible();
		boss = Boss.forRegion(region, config.showPuzzles());
		pathLevel = -1;
		if (boss != null && boss != Boss.WARDENS
			&& client.getVarbitValue(VarbitID.TOA_CLIENT_CURRENT_PATH) == boss.pathId)
		{
			// toa_hud_draw displays these varbits directly. Reading the underlying value
			// works with hidden/unloaded HUD widgets and avoids a previous room's text.
			// Require matching room/path state while the server switches between rooms.
			int level = client.getVarbitValue(boss.levelVarbit);
			if (level >= 0 && level <= 6) pathLevel = level;
		}
	}

	Boss getBoss() { return boss; }
	int getPathLevel() { return pathLevel; }
	InvocationSelection getSelection() { return selections.getSelection(); }
	String getLobbyStatus() { return showLobbyStatus ? captureStatus : null; }

	@Provides
	ToaPathwatchConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(ToaPathwatchConfig.class);
	}
}

package com.cornwall92.toapathwatch;

import java.util.Arrays;
import java.util.EnumSet;
import org.junit.Test;
import static org.junit.Assert.*;

/** Literal script-6729 payloads, independent of the plugin's UI indexes and point totals. */
public class PartyBuildReaderTest
{
	private Object[] partyBuild()
	{
		// CS2 parameters: role, party argument, count, score, tab, three 31-bit words.
		// Cache bits: Hardcore 4, Walk the Path 12, Double Trouble 30,
		// Keep Back 31, Stay Vigilant 32, Feeling Special 33, Insanity 44.
		return new Object[]{6729, 2, 12345, 7, 190, 2, 0x40001010, 0x2007, 0};
	}

	@Test public void leaderPayloadDecodesIndependentFixtureAcrossWordBoundary()
	{
		InvocationSelection result = InvocationReader.readPartyBuild(partyBuild());
		assertNotNull(result);
		assertEquals(EnumSet.of(Invocation.HARDCORE_RUN, Invocation.WALK_THE_PATH,
			Invocation.DOUBLE_TROUBLE, Invocation.KEEP_BACK, Invocation.STAY_VIGILANT,
			Invocation.FEELING_SPECIAL, Invocation.INSANITY), result.active);
		assertEquals(190, result.raidPoints);
	}

	@Test public void currentPartyMemberUsesTheSameSelectionWords()
	{
		Object[] args = partyBuild();
		args[1] = 1;
		InvocationSelection result = InvocationReader.readPartyBuild(args);
		assertNotNull(result);
		assertEquals(7, result.active.size());
		assertTrue(result.active.contains(Invocation.KEEP_BACK));
		assertEquals(190, result.raidPoints);
	}

	@Test public void firstInvocationUsesBitOneRatherThanBitZero()
	{
		InvocationSelection result = InvocationReader.readPartyBuild(
			new Object[]{6729, 1, 0, 1, 5, 2, 0x2, 0, 0});
		assertNotNull(result);
		assertEquals(EnumSet.of(Invocation.TRY_AGAIN), result.active);
	}

	@Test public void bitThirtyRemainsInFirstWord()
	{
		InvocationSelection result = InvocationReader.readPartyBuild(
			new Object[]{6729, 2, 0, 1, 20, 2, 0x40000000, 0, 0});
		assertNotNull(result);
		assertEquals(EnumSet.of(Invocation.DOUBLE_TROUBLE), result.active);
	}

	@Test public void bitThirtyOneStartsSecondWordAtBitZero()
	{
		InvocationSelection result = InvocationReader.readPartyBuild(
			new Object[]{6729, 2, 0, 1, 10, 2, 0, 0x1, 0});
		assertNotNull(result);
		assertEquals(EnumSet.of(Invocation.KEEP_BACK), result.active);
	}

	@Test public void lastOrdinaryInvocationUsesSecondWordBitThirteen()
	{
		InvocationSelection result = InvocationReader.readPartyBuild(
			new Object[]{6729, 2, 0, 1, 50, 2, 0, 0x2000, 0});
		assertNotNull(result);
		assertEquals(EnumSet.of(Invocation.INSANITY), result.active);
	}

	@Test public void zeroInvocationsAreKnownForBothCurrentPartyRoles()
	{
		for (int role : new int[]{1, 2})
		{
			InvocationSelection result = InvocationReader.readPartyBuild(
				new Object[]{6729, role, 0, 0, 0, 2, 0, 0, 0});
			assertNotNull(result);
			assertTrue(result.active.isEmpty());
			assertEquals(0, result.raidPoints);
		}
	}

	@Test public void otherPartyAndApplicantRolesAreRejectedEvenWithValidSelection()
	{
		for (int role : new int[]{-1, 0, 3, 4, 5, Integer.MAX_VALUE})
		{
			Object[] args = partyBuild();
			args[1] = role;
			assertNull("role " + role, InvocationReader.readPartyBuild(args));
		}
	}

	@Test public void readerAcceptsAllKnownTabsForCallerToApplyVisibilityPolicy()
	{
		for (int tab = 0; tab <= 3; tab++)
		{
			Object[] args = partyBuild();
			args[5] = tab;
			assertNotNull("tab " + tab, InvocationReader.readPartyBuild(args));
		}
		for (int tab : new int[]{-1, 4, Integer.MAX_VALUE})
		{
			Object[] args = partyBuild();
			args[5] = tab;
			assertNull("tab " + tab, InvocationReader.readPartyBuild(args));
		}
	}

	@Test public void unrelatedIntegerPartyArgumentDoesNotChangeSelection()
	{
		for (int value : new int[]{-1, 0, 0x12345678})
		{
			Object[] args = partyBuild();
			args[2] = value;
			InvocationSelection result = InvocationReader.readPartyBuild(args);
			assertNotNull(result);
			assertEquals(190, result.raidPoints);
		}
	}

	@Test public void mismatchingNegativeAndExcessiveActiveCountsAreRejected()
	{
		for (int count : new int[]{-1, 0, 6, 8, 45, Integer.MAX_VALUE})
		{
			Object[] args = partyBuild();
			args[3] = count;
			assertNull("count " + count, InvocationReader.readPartyBuild(args));
		}
	}

	@Test public void mismatchingNegativeAndExcessiveScoresAreRejected()
	{
		for (int points : new int[]{-1, 0, 189, 191, Integer.MAX_VALUE})
		{
			Object[] args = partyBuild();
			args[4] = points;
			assertNull("points " + points, InvocationReader.readPartyBuild(args));
		}
	}

	@Test public void reservedAndUnsupportedBitsCannotBeSilentlyDiscarded()
	{
		int[][] unsupported = {
			{6, 0x1},          // First word bit zero is reserved.
			{6, 0x80000000},   // The words use 31 bits, not 32.
			{7, 0x4000},       // Blazing Tombs I is outside the supported ordinary set.
			{7, 0x8000},       // Blazing Tombs II is likewise unsupported.
			{7, 0x40000000},
			{7, 0x80000000},
			{8, 0x1},
			{8, 0x80000000}
		};
		for (int[] bit : unsupported)
		{
			Object[] args = partyBuild();
			args[bit[0]] = (Integer) args[bit[0]] | bit[1];
			assertNull("argument " + bit[0] + ", mask " + bit[1], InvocationReader.readPartyBuild(args));
		}
	}

	@Test public void nullShortAndExtraArgumentPayloadsAreRejected()
	{
		assertNull(InvocationReader.readPartyBuild(null));
		for (int length : new int[]{0, 1, 5, 8, 10})
		{
			Object[] args = Arrays.copyOf(partyBuild(), length);
			if (length == 10) args[9] = 0;
			assertNull("length " + length, InvocationReader.readPartyBuild(args));
		}
	}

	@Test public void everyArgumentRequiresAnIntegerWithoutCoercion()
	{
		for (int index = 0; index < 9; index++)
		{
			for (Object invalid : new Object[]{null, "0", 0L, Boolean.FALSE})
			{
				Object[] args = partyBuild();
				args[index] = invalid;
				assertNull("argument " + index, InvocationReader.readPartyBuild(args));
			}
		}
	}

	@Test public void differentScriptAndReorderedParametersAreRejected()
	{
		Object[] wrongScript = partyBuild();
		wrongScript[0] = 6754;
		assertNull(InvocationReader.readPartyBuild(wrongScript));
		Object[] swappedCountAndScore = partyBuild();
		swappedCountAndScore[3] = 190;
		swappedCountAndScore[4] = 7;
		assertNull(InvocationReader.readPartyBuild(swappedCountAndScore));
		Object[] swappedWords = partyBuild();
		swappedWords[6] = 0x2007;
		swappedWords[7] = 0x40001010;
		assertNull(InvocationReader.readPartyBuild(swappedWords));
	}

	@Test public void laterEmptyPresetDoesNotMutateEarlierSnapshot()
	{
		InvocationSelection first = InvocationReader.readPartyBuild(partyBuild());
		InvocationSelection cleared = InvocationReader.readPartyBuild(
			new Object[]{6729, 2, 12345, 0, 0, 2, 0, 0, 0});
		assertNotNull(first);
		assertNotNull(cleared);
		assertEquals(7, first.active.size());
		assertEquals(190, first.raidPoints);
		assertTrue(cleared.active.isEmpty());
	}
}

package com.cornwall92.toapathwatch;

import java.util.EnumMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class RaidSelectionTrackerTest
{
	private static final int LOBBY = 13454;
	private static final int NEXUS = 14160;
	private static final int AKKHA = 14676;
	private static final int OUTSIDE = 12850;

	private InvocationSelection selection(Invocation... active)
	{
		Map<Invocation, Boolean> states = new EnumMap<>(Invocation.class);
		for (Invocation invocation : Invocation.values()) states.put(invocation, false);
		for (Invocation invocation : active) states.put(invocation, true);
		return InvocationSelection.validate(states, null);
	}

	@Test public void repeatedLobbyTicksPreserveFreshCapture()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.WALK_THE_PATH);
		tracker.capture(captured);
		tracker.update(LOBBY, 0);
		tracker.update(LOBBY, 0);
		tracker.update(NEXUS, 50);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void delayedRaidLevelCanValidateInNexus()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.PATHFINDER);
		tracker.capture(captured);
		tracker.update(NEXUS, 0);
		assertTrue(tracker.isInRaid());
		assertNull(tracker.getSelection());
		tracker.update(NEXUS, 40);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void entryValidationExpiresAfterFiveObservations()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		for (int i = 0; i < 5; i++) tracker.update(NEXUS, 0);
		tracker.update(NEXUS, 50);
		assertNull(tracker.getSelection());
	}

	@Test public void entryValidationStillWorksOnFifthObservation()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.WALK_THE_PATH);
		tracker.capture(captured);
		for (int i = 0; i < 4; i++) tracker.update(NEXUS, 0);
		tracker.update(NEXUS, 50);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void leavingNexusClosesPendingValidation()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		tracker.update(NEXUS, 0);
		tracker.update(AKKHA, 50);
		tracker.update(NEXUS, 50);
		assertNull(tracker.getSelection());
	}

	@Test public void temporaryUnknownRegionDoesNotEraseRaidCapture()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.WALK_THE_PATH);
		tracker.capture(captured);
		tracker.update(NEXUS, 50);
		for (int i = 0; i < 3; i++) tracker.update(-1, 0);
		assertTrue(tracker.isInRaid());
		tracker.update(AKKHA, 50);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void persistentUnknownRegionEventuallyClearsRaid()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		tracker.update(NEXUS, 50);
		for (int i = 0; i < 4; i++) tracker.update(-1, 0);
		assertFalse(tracker.isInRaid());
		assertNull(tracker.getSelection());
		tracker.update(AKKHA, 50);
		assertNull(tracker.getSelection());
	}

	@Test public void confirmedExitClearsImmediatelyAndCannotReusePriorCapture()
	{
		for (int destination : new int[]{LOBBY, OUTSIDE})
		{
			RaidSelectionTracker tracker = new RaidSelectionTracker();
			tracker.capture(selection(Invocation.WALK_THE_PATH));
			tracker.update(NEXUS, 50);
			tracker.update(destination, 50);
			assertFalse(tracker.isInRaid());
			assertNull(tracker.getSelection());
			tracker.update(NEXUS, 50);
			assertNull(tracker.getSelection());
		}
	}

	@Test public void frozenCaptureSurvivesLaterScoreChangesAndCaptureAttempts()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.RUN_FOR_IT);
		tracker.capture(captured);
		tracker.update(NEXUS, 20);
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		tracker.invalidateLobby();
		tracker.update(AKKHA, 0);
		tracker.update(NEXUS, 50);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void newPresetReplacesPreviousLobbySelection()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.RUN_FOR_IT));
		InvocationSelection replacement = selection(Invocation.WALK_THE_PATH);
		tracker.capture(replacement);
		tracker.update(NEXUS, 50);
		assertSame(replacement, tracker.getSelection());
	}

	@Test public void invalidatedGridDoesNotReuseEarlierPreset()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.RUN_FOR_IT));
		tracker.capture(null);
		tracker.update(NEXUS, 20);
		assertNull(tracker.getSelection());
	}

	@Test public void midRaidEnablingDoesNotInventSelection()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.update(AKKHA, 300);
		assertTrue(tracker.isInRaid());
		assertNull(tracker.getSelection());
	}

	@Test public void zeroInvocationRaidIsKnownRatherThanMissing()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection empty = selection();
		tracker.capture(empty);
		tracker.update(NEXUS, 0);
		assertSame(empty, tracker.getSelection());
		assertTrue(tracker.getSelection().active.isEmpty());
	}

	@Test public void resetClearsFrozenAndPendingData()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		tracker.update(NEXUS, 0);
		tracker.reset();
		tracker.update(NEXUS, 50);
		assertNull(tracker.getSelection());
		tracker.reset();
		assertFalse(tracker.isInRaid());
	}
}

package com.cornwall92.toapathwatch;

import java.util.EnumMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.*;

public class ReferenceTest
{
	private Map<Invocation, Boolean> blank()
	{
		Map<Invocation, Boolean> states = new EnumMap<>(Invocation.class);
		for (Invocation inv : Invocation.values()) states.put(inv, false);
		return states;
	}

	@Test public void completeZeroRaidIsKnownEmpty()
	{
		InvocationSelection selection = InvocationSelection.validate(blank(), 0);
		assertNotNull(selection);
		assertTrue(selection.active.isEmpty());
	}

	@Test public void incompleteReadIsUnknown()
	{
		Map<Invocation, Boolean> states = blank();
		states.remove(Invocation.INSANITY);
		assertNull(InvocationSelection.validate(states, 0));
	}

	@Test public void greyLoadingFrameCannotOverwriteNonzeroRaid()
	{
		assertNull(InvocationSelection.validate(blank(), 300));
	}

	@Test public void allInvocationsContributeToScoreIncludingHiddenGlobals()
	{
		Map<Invocation, Boolean> states = blank();
		states.put(Invocation.PATHFINDER, true);
		states.put(Invocation.WALK_THE_PATH, true);
		states.put(Invocation.NEED_LESS_HELP, true);
		InvocationSelection selection = InvocationSelection.validate(states, 115);
		assertNotNull(selection);
		assertEquals(3, selection.active.size());
		assertNull(InvocationSelection.validate(states, 110));
	}

	@Test public void unknownStateIsNotInactive()
	{
		Map<Invocation, Boolean> states = blank();
		states.put(Invocation.KEEP_BACK, null);
		assertNull(InvocationSelection.validate(states, 0));
	}

	@Test public void namesKeepPunctuationAndIgnoreGameColorTags()
	{
		assertSame(Invocation.FEELING_SPECIAL, Invocation.fromName("<col=d39034>Feeling Special?</col>"));
		assertSame(Invocation.MEDIC, Invocation.fromName("Medic!"));
		assertSame(Invocation.MIND_THE_GAP, Invocation.fromName("Mind the Gap!"));
		assertNull(Invocation.fromName("New unrecognised invocation"));
	}

	@Test public void catalogHasAll44UniquePositions()
	{
		assertEquals(44, Invocation.values().length);
		Set<Integer> positions = new HashSet<>();
		for (Invocation inv : Invocation.values())
		{
			assertTrue(positions.add(inv.uiIndex));
			assertSame(inv, Invocation.fromName(inv.displayName));
		}
		for (int i = 0; i < 44; i++) assertTrue(positions.contains(i));
	}

	@Test public void mechanicsChangeOnlyAtTwoAndFour()
	{
		assertEquals(0, PathMechanics.tier(1));
		assertEquals(1, PathMechanics.tier(2));
		assertEquals(1, PathMechanics.tier(3));
		assertEquals(2, PathMechanics.tier(4));
		for (Boss boss : Boss.values())
		{
			assertEquals(PathMechanics.describe(boss, 4), PathMechanics.describe(boss, 6));
		}
	}

	@Test public void scalingContinuesBeyondLastMechanicTier()
	{
		int[] expected = {0, 8, 13, 18, 23, 28, 33};
		for (int i = 0; i < expected.length; i++) assertEquals(expected[i], PathMechanics.statBonusPercent(i));
	}

	@Test(expected = IllegalArgumentException.class) public void missingLevelIsNotSilentlyTreatedAsZero()
	{
		PathMechanics.describe(Boss.AKKHA, -1);
	}

	@Test public void wardensHaveNoInventedPathTier()
	{
		assertEquals(-1, Boss.WARDENS.levelVarbit);
		assertEquals("No separate Warden path level.", PathMechanics.describe(Boss.WARDENS, -1).get(0));
		assertSame(Boss.WARDENS, Boss.forRegion(15184, false));
		assertSame(Boss.WARDENS, Boss.forRegion(15696, false));
	}

	@Test public void puzzleVisibilityIsOptional()
	{
		assertNull(Boss.forRegion(14674, false));
		assertSame(Boss.AKKHA, Boss.forRegion(14674, true));
		assertSame(Boss.AKKHA, Boss.forRegion(14676, false));
		assertTrue(Boss.isRaidRegion(14674));
		assertFalse(Boss.isRaidRegion(13454));
	}
}

package com.cornwall92.toapathwatch;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class RegionResolverTest
{
	private Client client;
	private Player player;
	private WorldView worldView;

	@Before public void setUp()
	{
		client = mock(Client.class);
		player = mock(Player.class);
		worldView = mock(WorldView.class);
		when(worldView.getId()).thenReturn(WorldView.TOPLEVEL);
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getWorldView(WorldView.TOPLEVEL)).thenReturn(worldView);
		when(player.getLocalLocation()).thenReturn(at(12, 12));
	}

	private LocalPoint at(int sceneX, int sceneY)
	{
		return new LocalPoint(sceneX * 128 + 64, sceneY * 128 + 64, WorldView.TOPLEVEL);
	}

	private int[][][] instance()
	{
		int[][][] chunks = new int[4][13][13];
		when(worldView.isInstance()).thenReturn(true);
		when(worldView.getInstanceTemplateChunks()).thenReturn(chunks);
		return chunks;
	}

	@Test public void missingPlayerIsUnknown()
	{
		when(client.getLocalPlayer()).thenReturn(null);
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void missingLocalPointIsUnknown()
	{
		when(player.getLocalLocation()).thenReturn(null);
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void missingWorldViewIsUnknown()
	{
		when(client.getWorldView(WorldView.TOPLEVEL)).thenReturn(null);
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void ordinaryWorldUsesPlayersWorldView()
	{
		when(worldView.getBaseX()).thenReturn(52 * 64);
		when(worldView.getBaseY()).thenReturn(142 * 64);
		assertEquals(13454, RegionResolver.region(client));
		verify(client, never()).getTopLevelWorldView();
	}

	@Test public void validInstanceUsesTemplateRegion()
	{
		int[][][] chunks = instance();
		chunks[0][1][1] = (57 * 8 << 14) | (84 * 8 << 3);
		assertEquals(Boss.AKKHA.bossRegion, RegionResolver.region(client));
	}

	@Test public void unloadedChunkIsUnknownInsteadOfSyntheticOutsideRegion()
	{
		int[][][] chunks = instance();
		chunks[0][1][1] = -1;
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void missingInstanceArrayIsUnknown()
	{
		when(worldView.isInstance()).thenReturn(true);
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void invalidOrUnloadedPlaneIsUnknown()
	{
		int[][][] chunks = instance();
		when(worldView.getPlane()).thenReturn(-1);
		assertEquals(-1, RegionResolver.region(client));
		when(worldView.getPlane()).thenReturn(4);
		assertEquals(-1, RegionResolver.region(client));
		when(worldView.getPlane()).thenReturn(0);
		chunks[0] = null;
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void missingOrShortChunkRowsAreUnknown()
	{
		int[][][] chunks = instance();
		chunks[0][1] = null;
		assertEquals(-1, RegionResolver.region(client));
		chunks[0][1] = new int[1];
		assertEquals(-1, RegionResolver.region(client));
		chunks[0] = new int[1][13];
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void sceneCoordinatesOutsideTemplateGridAreUnknown()
	{
		instance();
		when(player.getLocalLocation()).thenReturn(at(-1, 12));
		assertEquals(-1, RegionResolver.region(client));
		when(player.getLocalLocation()).thenReturn(at(12, -1));
		assertEquals(-1, RegionResolver.region(client));
		when(player.getLocalLocation()).thenReturn(at(104, 12));
		assertEquals(-1, RegionResolver.region(client));
		when(player.getLocalLocation()).thenReturn(at(12, 104));
		assertEquals(-1, RegionResolver.region(client));
	}
}

